import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
public final class AnalyticsDtos { public record Summary(BigDecimal revenue,BigDecimal expenses,BigDecimal profit,BigDecimal margin,int orders,int unitsSold,BigDecimal averageOrderValue){} public record DailyPoint(LocalDate date,BigDecimal revenue,BigDecimal expenses,BigDecimal profit,int orders,int unitsSold){} public record ProductPerformance(UUID productId,String productName,int unitsSold,BigDecimal revenue,BigDecimal productCost,BigDecimal profit,BigDecimal margin,BigDecimal salesShare){} public record ExpenseBreakdown(String category,BigDecimal amount,BigDecimal share){} public record Dashboard(Summary today,Summary period, List<DailyPoint> trend,List<ProductPerformance> topProducts,List<ExpenseBreakdown> expenseBreakdown,List<String> insights){} public record PeriodReport(LocalDate from,LocalDate to,Summary summary,List<DailyPoint> trend,List<ProductPerformance> products,List<ExpenseBreakdown> expenses,List<String> insights){} }
